import fs from "node:fs/promises";
import assert from "node:assert/strict";
import {performance} from "node:perf_hooks";
import {createHash} from "node:crypto";
import {dataChanges} from "../backend/change-set.mjs";
import {prepareMutationSettings} from "../backend/mutation-settings.mjs";
import {dataChanges as originalChanges} from "./reference-change-set.mjs";
import {prepareMutationSettings as originalSettings} from "./reference-mutation-settings.mjs";
const observations=[];
for(const count of [1000,10000]){
 const before={teams:[],projects:[],resources:[],risks:[],allocations:{},actualAllocations:{},workCalendar:{},personCalendar:{}};
 for(let i=0;i<50000;i++)before.allocations["t|p"+i+"|2026-01"]=0.25;
 for(let i=0;i<10000;i++)before.actualAllocations["r|p"+i+"|2026-01"]=0.01;
 for(let i=0;i<count;i++){
   const date=new Date(Date.UTC(2026,0,1+Math.floor(i/200))).toISOString().slice(0,10);
   before.personCalendar["r"+(i%200)+"|"+date+"|leave"]={type:"leave",hours:1,label:"Synthetic calendar"};
 }
 const after=structuredClone(before);after.allocations["t|p0|2026-01"]=0.5;
 const results={};
 const measure=(name)=>{const start=performance.now();let settings,changes;if(name==="reference"){settings=originalSettings(before,after);changes=originalChanges(before,after)}else{settings=prepareMutationSettings(before,after,{validatedCalendars:true});changes=dataChanges(before,after,{settings})}return {ms:performance.now()-start,changes,sql:{assignments:settings.assignments,values:settings.values}}};
 for(const name of ["reference","candidate"])measure(name);
 const samples={reference:[],candidate:[]};
 for(let i=0;i<9;i++)for(const name of i%2?["candidate","reference"]:["reference","candidate"]){const result=measure(name);samples[name].push(result.ms);results[name]=result;}
 assert.deepEqual(results.reference.changes,results.candidate.changes);assert.deepEqual(results.reference.sql,results.candidate.sql);
 observations.push({calendarDays:count,samples,changeSetSha256:createHash("sha256").update(JSON.stringify(results.candidate.changes)).digest("hex")});
}
await fs.writeFile(new URL("./diff-cost.json",import.meta.url),JSON.stringify(observations,null,2)+"\n");console.log(JSON.stringify(observations.map(r=>({calendarDays:r.calendarDays,medians:Object.fromEntries(Object.entries(r.samples).map(([k,v])=>[k,[...v].sort((a,b)=>a-b)[4]]))}))));
